  'edge':          { icon: '\u{1F537}', device: 'Navegador Edge',    os: 'Windows', viewport: '1280x720',  color: '#0078D7', bg: '#E5F1FB', order: 3 },
  'mobile-chrome': { icon: '\u{1F4F1}', device: 'Android (Pixel 7)',  os: 'Android', viewport: '412x915',   color: '#34A853', bg: '#E6F4EA', order: 4 },
  'mobile-safari': { icon: '\u{1F34E}', device: 'iOS (iPhone 14)',   os: 'iOS',     viewport: '390x844',   color: '#FF6B6B', bg: '#FFF0F0', order: 5 },
  'tablet':        { icon: '\u{1F4F2}', device: 'iPad (gen 7)',      os: 'iPadOS',  viewport: '810x1080',  color: '#8E44AD', bg: '#F4ECF7', order: 6 },
};

const getDevice = (name) => deviceMap[name] || { icon: '\u{1F5A5}', device: name || 'N/A', os: '-', viewport: '-', color: '#64748B', bg: '#F1F5F9' };

// Spec label
const specFiles = body.specFiles || [...new Set(testResults.map(r => r.spec))];
const folders = body.folders || [...new Set(testResults.map(r => r.folder).filter(Boolean))];
let specLabel;
if (specFiles.length === 1) {
  specLabel = specFiles[0];
} else if (specFiles.length > 1) {
  specLabel = folders.join(', ') + ' (' + specFiles.length + ' specs)';
} else {
  specLabel = suite;
}

// Specs que fallaron
const failedSpecs = testResults
  .filter(t => t.state === 'failed')
  .map(t => (t.project || '') + ' > ' + t.spec + ' > ' + t.title)
  .join(', ') || 'Ninguno';

// Subject
const subject = 'Portal Pacientes \u{1F9EA} Playwright# ' + specLabel + ' ' + statusText + ' — ' + passes + '✅ ' + failures + '❌ | ' + browsersLabel + ' | ' + fecha;

// Badge
const badgeHtml = allPassed
  ? '<span style="background:#F0FDF4; color:#16A34A; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">✅ TODO PASSED</span>'
  : '<span style="background:#FEF2F2; color:#DC2626; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">❌ HAY FALLOS</span>';

// Pass rate badge
const prColor = passRate >= 95 ? '#16A34A' : passRate >= 80 ? '#F59E0B' : '#DC2626';
const prBg = passRate >= 95 ? '#F0FDF4' : passRate >= 80 ? '#FFFBEB' : '#FEF2F2';
const passRateBadge = '<span style="background:' + prBg + '; color:' + prColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px; white-space:nowrap;">Pass Rate:&nbsp;' + passRate + '%</span>';

// Browser badges for header — ordenados: navegadores primero, luego mobile/tablet — siempre 2 por fila
const sortedBadgeProjects = [...projects].sort((a, b) => {
  const orderA = (deviceMap[a] || {}).order || 99;
  const orderB = (deviceMap[b] || {}).order || 99;
  return orderA - orderB;
});
const makeBadge = (p) => {
  const d = getDevice(p);
  return '<span style="background:rgba(255,255,255,0.15); color:#FFFFFF; padding:4px 12px; border-radius:12px; font-weight:600; font-size:11px; margin-right:4px; display:inline-block;">' + d.icon + ' ' + d.device + ' <span style="color:#CFE2FF; font-weight:400;">(' + d.os + ' · ' + d.viewport + ')</span></span>';
};
const badgeRows = [];
for (let i = 0; i < sortedBadgeProjects.length; i += 2) {
  badgeRows.push(sortedBadgeProjects.slice(i, i + 2).map(makeBadge).join(' '));
}
const browserBadges = badgeRows
  .map((row, i) => '<div style="' + (i < badgeRows.length - 1 ? 'margin-bottom:6px;' : '') + '">' + row + '</div>')
  .join('');

// Cards
const cardHtml = (value, label, color, bg) => {
  return '<td width="20%" style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 16px;"><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:28px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(passes, '✅ PASADOS', '#16A34A', '#F0FDF4')
  + cardHtml(failures, '❌ FALLIDOS', '#DC2626', '#FEF2F2')
  + cardHtml(skipped, '⚠️ SKIPPED', '#F59E0B', '#FFFBEB')
  + cardHtml(passRate + '%', '\u{1F4CA} PASS RATE', prColor, prBg)
  + cardHtml(durationStr, '⏱ DURACION', '#2563EB', '#EFF6FF');

// ─── Resumen por Spec ───
const specNames = [...new Set(testResults.map(r => r.spec).filter(Boolean))];
const specSummaryRows = specNames.map(specName => {
  const specTests = testResults.filter(t => t.spec === specName);
  const sPassed = specTests.filter(t => t.state === 'passed').length;
  const sFailed = specTests.filter(t => t.state === 'failed').length;
  const sSkipped = specTests.filter(t => t.state === 'skipped').length;
  const sExecuted = specTests.length - sSkipped;
  const sPassRate = sExecuted > 0 ? Math.round((sPassed / sExecuted) * 100) : 0;
  const sPrColor = sPassRate >= 95 ? '#16A34A' : sPassRate >= 80 ? '#F59E0B' : '#DC2626';
  const sIcon = sFailed === 0 ? '\u{1F7E2}' : '\u{1F534}';

  return '<tr>'
    + '<td style="padding:10px 14px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6;">' + sIcon + ' ' + specName + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#16A34A; font-weight:700; text-align:center;">' + sPassed + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:' + (sFailed > 0 ? '#DC2626' : '#64748B') + '; font-weight:700; text-align:center;">' + sFailed + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:' + (sSkipped > 0 ? '#F59E0B' : '#64748B') + '; font-weight:700; text-align:center;">' + sSkipped + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + (sPassRate >= 95 ? '#F0FDF4' : sPassRate >= 80 ? '#FFFBEB' : '#FEF2F2') + '; color:' + sPrColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif;">' + sPassRate + '%</span></td>'
    + '</tr>';
}).join('');

const specSummaryHtml = '<div style="padding:0 20px 20px;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
  + '<thead><tr style="background:#0D1846;">'
  + '<th align="left" style="padding:10px 14px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Spec</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Passed</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Failed</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Skip</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Pass Rate</th>'
  + '</tr></thead>'
  + '<tbody>' + specSummaryRows + '</tbody>'
  + '</table></div>';

// ─── Tablas separadas por browser (navegadores primero, luego mobile) ───
const sortedProjects = [...projects].sort((a, b) => {
  const orderA = (deviceMap[a] || {}).order || 99;
  const orderB = (deviceMap[b] || {}).order || 99;
  return orderA - orderB;
});

const browserSections = sortedProjects.map(projectName => {
  const d = getDevice(projectName);
  const browserTests = testResults.filter(t => t.project === projectName).sort((a, b) => {
    const specCompare = (a.spec || '').localeCompare(b.spec || '');
    if (specCompare !== 0) return specCompare;
    return (a.title || '').localeCompare(b.title || '');
  });
  const bPasses = browserTests.filter(t => t.state === 'passed').length;
  const bFailures = browserTests.filter(t => t.state === 'failed').length;
  const bSkipped = browserTests.filter(t => t.state === 'skipped').length;
  const bTotal = browserTests.length;
  const bExecuted = bTotal - bSkipped;
  const bPassRate = bExecuted > 0 ? Math.round((bPasses / bExecuted) * 100) : 0;
  const bPrColor = bPassRate >= 95 ? '#16A34A' : bPassRate >= 80 ? '#F59E0B' : '#DC2626';
  const bAllPassed = bFailures === 0;
  const bBadge = bAllPassed
    ? '<span style="background:#F0FDF4; color:#16A34A; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px;">✅ ' + bPasses + '/' + bTotal + ' PASSED</span>'
    : '<span style="background:#FEF2F2; color:#DC2626; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px;">❌ ' + bFailures + ' FAILED</span>';

  const rows = browserTests.map(t => {
    let sColor, sBg, sLabel;
    if (t.state === 'passed') { sColor = '#16A34A'; sBg = '#F0FDF4'; sLabel = 'PASSED'; }
    else if (t.state === 'failed') { sColor = '#DC2626'; sBg = '#FEF2F2'; sLabel = 'FAILED'; }
    else { sColor = '#F59E0B'; sBg = '#FFFBEB'; sLabel = 'SKIPPED'; }
    const dot = t.state === 'passed' ? '\u{1F7E2}' : t.state === 'failed' ? '\u{1F534}' : '\u{1F7E1}';
    const errorText = t.err ? (t.err.length > 200 ? t.err.substring(0, 200) + '...' : t.err) : '—';

    return '<tr>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-size:16px; text-align:center;">' + dot + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + (t.spec || 'N/A') + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + (t.title || '') + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + sBg + '; color:' + sColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif;">' + sLabel + '</span></td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#2563EB; font-weight:600; text-align:center;">' + t.duration + 'ms</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#94A3B8; max-width:200px; word-break:break-word;">' + errorText + '</td>'
      + '</tr>';
  }).join('');

  return '<div style="padding:0 20px 20px;">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
    // Browser header
    + '<tr><td colspan="6" style="background:' + d.bg + '; border-left:4px solid ' + d.color + '; padding:14px 16px;">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'
    + '<td style="vertical-align:middle;">'
    + '<div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:15px; font-weight:700; color:' + d.color + ';">' + d.icon + ' ' + d.device + '</div>'
    + '<div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; color:#64748B; margin-top:2px;">' + d.os + ' · ' + d.viewport + ' · Pass Rate: <strong style="color:' + bPrColor + ';">' + bPassRate + '%</strong></div>'
    + '</td>'
    + '<td style="text-align:right; vertical-align:middle;">' + bBadge + '</td>'
    + '</tr></table>'
    + '</td></tr>'
    // Table header
    + '<tr style="background:#F4F6F8;">'
    + '<th style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B; width:30px;"></th>'
    + '<th align="left" style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Spec</th>'
    + '<th align="left" style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Test Case</th>'
    + '<th align="center" style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Estado</th>'
    + '<th align="center" style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Duracion</th>'
    + '<th align="left" style="padding:8px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Error</th>'
    + '</tr>'
    // Rows
    + rows
    + '</table></div>';
}).join('');

// Full HTML
const htmlBody = '<div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; max-width:880px; margin:0 auto; background:#F4F6FB;">'
  // Header
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0D1846;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE · PORTAL PACIENTES</div>'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;"><tr>'
  + '<td style="vertical-align:middle;">'
  + '<div style="color:#FFFFFF; font-size:22px; font-weight:700;">'
  + '<span style="background:rgba(255,255,255,0.15); padding:4px 12px; border-radius:5px; margin-right:8px; font-size:14px; font-weight:800;">Playwright</span>'
  + 'QA Automation Report — ' + specLabel + '</div>'
  + '<div style="color:#FFFFFF; font-size:16px; margin-top:10px;"><strong style="font-size:20px;">' + totalTests + '</strong> test(s) ejecutados · <span style="color:#CFE2FF;">' + fecha + '</span> · ' + passRateBadge + '</div>'
  + '<div style="margin-top:8px;">' + browserBadges + '</div>'
  + '</td>'
  + '<td style="text-align:right; vertical-align:middle;">' + badgeHtml + '</td>'
  + '</tr></table>'
  + '</td></tr></table>'
  // Cards
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'
  // Spec summary
  + '<div style="padding:4px 20px 8px;"><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">RESUMEN POR SPEC</div></div>'
  + specSummaryHtml
  // Browser sections
  + '<div style="padding:4px 20px 8px;"><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">DETALLE POR BROWSER</div></div>'
  + browserSections
  // Footer
  + '<div style="padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;">'
  + 'Generado automáticamente — WF3 QA Automation Report · Portal Pacientes'
  + '</div></div>';

return [{ json: { subject, body: htmlBody } }];
